// Aztec
// For the #WCCChallenge << Chalchiuhtlicue, or Mesoamerican design >> (join the discord! https://discord.gg/S8c7qcjw2b)

/*
 * This week played with some designs inspired by mesoamerican cultures, mainly aztec, huichol and toltec
 * Even came across some very interesting study of their art (not limited to patterns but also architecture, sculpture, etc)
 * https://www.facebook.com/watch/live/?ref=watch_permalink&v=544351250379114 - but didn't go too deep, mostly used some inspiration
 *
 * The code challenge was to create some patterns that could be used either linearly, or circularly, by wrapping
 * the generator function into a coordinate transformation function (cartesian or polar). The code is still a bit messy,
 * and didn't spend much time into colors or more interesting compositions, may revisit later
 */

let cw, ch
let mainColor = '#32312e'
let bgColor = '#f5f2e3'

function setup() {
  cw = windowWidth
  ch = windowHeight
  pixelDensity(1)
  createCanvas(cw, ch)
  background(bgColor)
  angleMode(DEGREES)
  createDesign()
}

// On click, create a new design
function mousePressed() {
  background(bgColor)
  createDesign()
}

let cartesian = (x0, y0, x, y, w, h) => {
  return [x0 + x, y0 + y]
}

let polar = (t0, r0, t, r, w, h) => {
  let theta = t0 + t
  let radius = r0 + h - r
  // let y = r0 + h - r
  let res = [radius * cos(theta), radius * sin(theta)]
  return res
}

let weightedRandom = (arr) => {
  // First element is the weight. Pick a random array, and remove the weight from the array
  let totalWeight = arr.reduce((acc, v) => acc + v[0], 0)
  let r = random(totalWeight)
  let acc = 0
  for (let [weight, ...rest] of arr) {
    acc += weight
    if (r < acc) {
      return rest
    }
  }
  return arr[arr.length - 1]
}

let createDesign = () => {
  let method = random([createDesignCircular, createDesignLinear, createDesignDiagonal])
  method()
  texture = granulate(random(80, 150))
  image(texture, 0, 0)
}

let createDesignDiagonal = () => {
  // Similar to createDesignLinear, but rotate diagonally by 45 degrees
  // Get the size of the screen that will cover the whole screen
  let diagonal = sqrt(cw ** 2 + ch ** 2)
  let lastDesign = null
  let cch = diagonal
  let ccw = cch * cw / ch * sqrt(2)
  push()
  translate(cw / 2, ch / 2)
  rotate(-45)
  translate(-ccw / 2, -cch / 2)

  fill(mainColor)
  noStroke()

  for (let i = 0; i <= cch; i += (Math.max(0.001, Math.abs(h)) || 1)) {
    let designParams = weightedRandom(possiblePatterns)
    let _wG_1 = 0; while ((designParams[0] === lastDesign) && ++_wG_1 < 20000) {
      designParams = weightedRandom(possiblePatterns)
    }
    let design = designParams[0]
    let approxWidth = random(40, 100)
    // Make the number of slices the closest integer so divided is close to approxWidth
    let numSlices = floor(ccw / approxWidth)

    let sw = ccw / numSlices
    let sh = sw * designParams[2] * random(0.8, 1)
    for (let j = 0; j < numSlices; j++) {
      let sx = j * sw
      wrapDesign(design, cartesian, sx, i, sw * 1.005, sh, false, j)
    }
    h = sh
    h += random(2, 5)
    lastDesign = designParams[0]
  }
  pop()
}

let createDesignLinear = () => {
  let lastDesign = null
  fill(mainColor)
  noStroke()
  for (let i = 0; i <= ch; i += (Math.max(0.001, Math.abs(h)) || 1)) {
    let designParams = weightedRandom(possiblePatterns)
    let _wG_2 = 0; while ((designParams[0] === lastDesign) && ++_wG_2 < 20000) {
      designParams = weightedRandom(possiblePatterns)
    }
    let design = designParams[0]
    let approxWidth = random(40, 100)
    // Make the number of slices the closest integer so divided is close to approxWidth
    let numSlices = floor(cw / approxWidth)

    let sw = cw / numSlices
    let sh = sw * designParams[2] * random(0.8, 1)
    for (let j = 0; j < numSlices; j++) {
      let sx = j * sw
      wrapDesign(design, cartesian, sx, i, sw * 1.005, sh, false, j)
    }
    h = sh
    h += random(2, 5)
    lastDesign = designParams[0]
  }
}

let createDesignCircular = () => {
  push()
  translate(cw / 2, ch / 2)
  let h = random(100, 200)
  let maxR = sqrt(cw ** 2 + ch ** 2) / 2 // Diagonal
  fill(mainColor)
  noStroke()
  let lastDesign = null
  for (let r = 20; r < maxR; r += (Math.max(0.001, Math.abs(h)) || 1)) {
    let mult = map(r, 100, maxR, 1, 4)
    let numSlices = floor(random(4, 8) * mult) * 2
    // Calculate the approx length of the segment at the radius r
    let circumference = 2 * PI * r
    let segmentLength = circumference / numSlices

    let a = 360 / numSlices
    let designParams = weightedRandom(possiblePatterns)
    let _wG_3 = 0; while ((designParams[0] === lastDesign) && ++_wG_3 < 20000) {
      designParams = weightedRandom(possiblePatterns)
    }
    let design = designParams[0]
    h = designParams[1] * segmentLength
    for (let i = 0; i < numSlices; i++) {
      let angle = i * a
      wrapDesign(design, polar, angle, r, a * 1.005, h, true, i)
    }
    h *= random(1.1, 1.2)
    lastDesign = designParams[0]
  }
  pop()
}

let wrapDesign = (design, fn, x0, y0, w, h, isPolar, i) => {
  let fn2 = (a, b) => {
    return fn(x0, y0, a, b, w, h)
  }
  design(fn2, w, h, isPolar, i)
}

let patternTriangles = (fn, w, h, isPolar, i) => {
  triangle(
    ...fn(w / 2, 0),
    ...fn(w, h),
    ...fn(0, h),
  )
}

let patternTrianglesWithDot = (fn, w, h, isPolar, i) => {
  patternTriangles(fn, w, h, isPolar, i)
  let r = isPolar ? h / 3 : h / 4
  circle(
    ...fn(0, h/2),
    r
  )
}

let patternDoubleTriangle = (fn, w, h, isPolar, i) => {
  triangle(
    ...fn(w / 2, h/2),
    ...fn(w, h),
    ...fn(0, h),
  )
  triangle(
    ...fn(0, 0),
    ...fn(w/2, 0),
    ...fn(0, h/2),
  )
  triangle(
    ...fn(w/2, 0),
    ...fn(w, 0),
    ...fn(w, h/2),
  )
  let bh = h / 24
  beginShape()
  vertex(...fn(0, h*3/4 - bh))
  vertex(...fn(w/2, h/4 - bh))
  vertex(...fn(w, h*3/4 - bh))
  vertex(...fn(w, h*3/4 + bh))
  vertex(...fn(w/2, h/4 + bh))
  vertex(...fn(0, h*3/4 + bh))
  endShape()
}

let patternWave = (fn, w, h, isPolar, i) => {
  let bw = w/8
  let bh = h/8
  let points = [
    0, 7, 0, 0, 7, 0, 7, 5, 4, 5, 4, 3, 3, 3, 3, 6, 9, 6, 9, 7, 2, 7, 2, 2, 5, 2, 5, 4, 6, 4, 6, 1, 1, 1, 1, 7
  ]
  points = points.reduce((acc, v, i) => {
    if (i % 2 === 0) {
      acc.push([v, points[i + 1]])
    }
    return acc
  }, [])
  beginShape()
  for (let [x, y] of points) {
    vertex(...fn(x * bw, y * bh))
  }
  endShape(CLOSE)
}

let patternStacks = (fn, w, h, isPolar, i) => {
  let bw = w / 8
  let bh = h / 8
  for (let i = 0; i < 4; i++) {
    triangle(
      ...fn(i * bw, (3 - i) * bh),
      ...fn((i + 2) * bw, (3 - i) * bh),
      ...fn((i + 1) * bw, (4 - i) * bh),
    )
    triangle(
      ...fn(i * bw, (5 + i) * bh),
      ...fn((i + 2) * bw, (5 + i) * bh),
      ...fn((i + 1) * bw, (5 + i - 1) * bh),
    )
    triangle(
      ...fn((8 - i) * bw, (3 - i) * bh),
      ...fn((6 - i) * bw, (3 - i) * bh),
      ...fn((7 - i) * bw, (4 - i) * bh),
    )
    triangle(
      ...fn((8 - i) * bw, (5 + i) * bh),
      ...fn((6 - i) * bw, (5 + i) * bh),
      ...fn((7 - i) * bw, (5 + i - 1) * bh),
    )
  }
  quad(
    ...fn(4 * bw, 3 * bh),
    ...fn(5 * bw, 4 * bh),
    ...fn(4 * bw, 5 * bh),
    ...fn(3 * bw, 4 * bh),
  )
}

let patternConcentric = (fn, w, h, isPolar, i) => {
  let size = min(w, h)
  let n = 3
  let step = size / n
  for (let i = 0; i < n; i++) {
    if (i === n - 1) {
      noStroke()
      fill(mainColor)
    } else {
      noFill()
      stroke(mainColor)
    }
    strokeWeight(size / 16)
    circle(...fn(w/2, h/2), size - i * step)
  }
}

let patternSimpleDiamonds = (fn, w, h, isPolar, i) => {
  quad(
    ...fn(w/2, 0),
    ...fn(w, h/2),
    ...fn(w/2, h),
    ...fn(0, h/2),
  )
}

let patternPyramid = (fn, w, h, isPolar, i) => {
  let bw = w / 8
  let bh = h / 4
  let points = [
    3, 0, 5, 0, 5, 1, 6, 1, 6, 2, 7, 2, 7, 3, 8, 3, 8, 4, 0, 4, 0, 3, 1, 3, 1, 2, 2, 2, 2, 1, 3, 1
  ]
  points = points.reduce((acc, v, i) => {
    if (i % 2 === 0) {
      acc.push([v, points[i + 1]])
    }
    return acc
  }, [])
  // Draw the pyramid
  beginShape()
  for (let [x, y] of points) {
    vertex(...fn(x * bw, y * bh))
  }
  endShape()
}

let patternHollowPyramid = (fn, w, h, isPolar, i) => {
  let bw = w / 8
  let bh = h / 4
  let points = [
    3, 0, 5, 0, 5, 1, 6, 1, 6, 2, 7, 2, 7, 3, 8, 3, 8, 4,
    6, 4, 6, 3, 5, 3, 5, 2, 4, 2, 3, 2, 3, 3, 2, 3, 2, 4,
    0, 4, 0, 3, 1, 3, 1, 2, 2, 2, 2, 1, 3, 1
  ]
  points = points.reduce((acc, v, i) => {
    if (i % 2 === 0) {
      acc.push([v, points[i + 1]])
    }
    return acc
  }, [])
  // Draw the pyramid
  beginShape()
  for (let [x, y] of points) {
    vertex(...fn(x * bw, y * bh))
  }
  endShape()
}

let possiblePatterns = [
  [4, patternTriangles, 0.3, 0.5],
  [5, patternTrianglesWithDot, 0.3, 0.5],
  [3, patternDoubleTriangle, 0.8, 1.2],
  [4, patternWave, 0.7, 1.4],
  [6, patternStacks, 0.8, 1.2],
  [1, patternConcentric, 0.4, 0.6],
  [2, patternSimpleDiamonds, 0.4, 1.2],
  [2, patternPyramid, 0.3, 0.6],
  [2, patternHollowPyramid, 0.3, 0.6],
]

